// @pit: {"label": "Fetch Equibles core NVDA datasets once and cache raw JSON to /tmp"}
async ({ eq: { latestPrices, prices, valuationMultiples, revenueBreakdown, insiderTransactions, institutionalHolders, shortInterest, congressTrades }, workspace: { edit }, shell: { exec } }) => {
  const date = (await exec("date -u +%F")).stdout.trim();
  const jobs: Record<string, () => Promise<any>> = {
    latest: () => latestPrices({ tickers: ["NVDA"] }),
    prices: () => prices({ ticker: "NVDA", interval: "daily", limit: 260 }),
    valNow: () => valuationMultiples({ ticker: "NVDA" }),
    valHist: () => valuationMultiples({ ticker: "NVDA", history: true }),
    rev: () => revenueBreakdown({ ticker: "NVDA" }),
    insider: () => insiderTransactions({ ticker: "NVDA", limit: 100 }),
    holders: () => institutionalHolders({ ticker: "NVDA", limit: 15 }),
    short: () => shortInterest({ ticker: "NVDA" }),
    congress: () => congressTrades({ ticker: "NVDA", limit: 100 }),
  };
  const keys = Object.keys(jobs);
  const res = await Promise.allSettled(keys.map((k) => jobs[k]()));
  const out: any = { date };
  await Promise.all(keys.map(async (k, i) => {
    const r = res[i];
    const v = r.status === "fulfilled" ? r.value : { error: String(r.reason) };
    await edit(`/tmp/nvda/${k}.json`, { revision: null, changes: [{ kind: "replaceFile", content: JSON.stringify(v) }] });
    const s = JSON.stringify(v);
    out[k] = { len: s.length, url: v.url, count: v.count, preview: s.slice(0, 700) };
  }));
  return out;
}
